def rho(x,y):return float(pd.Series(x).corr(pd.Series(y),method='spearman')) if min(np.ptp(x),np.ptp(y))>0 else np.nan


def split(pT,mT,pN,mN,center):
    if pT>0 and pN>0:return (pT-pN)*((mT-center)+(mN-center))/2,(pT+pN)*(mT-mN)/2,0.,'SHARED_SELECTED_SUBTYPE'
    if pT>0:return np.nan,np.nan,pT*(mT-center),'ONLY_TUMOUR_SELECTED'
    return np.nan,np.nan,-pN*(mN-center),'ONLY_NORMAL_SELECTED'


